{
  "hechos": [
    {
      "id": "H1",
      "texto": "El puente La Concordia fue cerrado al tránsito de vehículos y peatones.",
      "paginas": ["P1", "P2", "P3", "P4", "P5"]
    },
    {
      "id": "H2",
      "texto": "Los estudiantes tienen que madrugar una hora más.",
      "paginas": ["P1"]
    },
    {
      "id": "H3",
      "texto": "La ruta alterna por El Cedral alarga el trayecto en aproximadamente 40 minutos.",
      "paginas": ["P1", "P2", "P3", "P4", "P5"]
    },
    {
      "id": "H4",
      "texto": "Cerca de 9.000 vehículos usan el puente cada día.",
      "paginas": ["P1", "P3"]
    },
    {
      "id": "H5",
      "texto": "Una inspección técnica encontró grietas en dos de las vigas principales.",
      "paginas": ["P2", "P4"]
    },
    {
      "id": "H6",
      "texto": "Carolina Mejía, comerciante del barrio Las Brisas, contó que los comerciantes del otro lado del río ya notan menos clientes.",
      "paginas": ["P3"]
    },
    {
      "id": "H7",
      "texto": "Quienes antes cruzaban el puente deberán tomar la vía El Cedral, lo que agrega cerca de 40 minutos.",
      "paginas": ["P1", "P2", "P3", "P4", "P5"]
    },
    {
      "id": "H8",
      "texto": "En el barrio Villa Nueva, la junta de acción comunal contó 450 familias que dependen del puente para ir a trabajar.",
      "paginas": ["P3"]
    },
    {
      "id": "H9",
      "texto": "Andrés Avendaño, habitante del barrio La Pradera, contó que se escuchaban crujidos en el puente desde hace semanas.",
      "paginas": ["P4"]
    },
    {
      "id": "H10",
      "texto": "La revisión técnica halló que dos vigas de soporte presentan grietas.",
      "paginas": ["P4"]
    },
    {
      "id": "H11",
      "texto": "Luz Dary Toro, docente del barrio Primero de Mayo, contó que hubo un trancón de más de dos horas en la vía El Cedral.",
      "paginas": ["P5"]
    },
    {
      "id": "H12",
      "texto": "En el barrio El Bosque, la junta de acción comunal contó 44 familias que dependen del puente para ir a trabajar.",
      "paginas": ["P5"]
    }
  ]
}
